import{c as t,Q as a,j as o,m as n}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":null}'),r={name:"getting-started/introduction.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>FinSight is a private, self-hosted financial copilot — a quiet way to understand, plan, and master your money.</p><p>It combines encrypted personal-finance storage, account and transaction management, budgeting, goals, reporting, and an AI-assisted Copilot. The primary deployment is a server you operate yourself, accessed from a browser or an installable PWA.</p><h2 id="why-finsight" tabindex="-1">Why FinSight <a class="header-anchor" href="#why-finsight" aria-label="Permalink to &quot;Why FinSight&quot;">​</a></h2><p>Most finance apps ask you to hand your ledger to a vendor. FinSight inverts that: <strong>your server is the source of truth</strong>. A single Docker image, a single <code>/data</code> volume, and your finances stay on hardware you control.</p><ul><li><strong>Local-first, encrypted.</strong> One SQLCipher database per user. The <code>users.db</code> registry holds only usernames, Argon2id verifiers, and wrapped keys — no financial records.</li><li><strong>You choose the AI.</strong> Use Ollama to keep inference on your infrastructure, or opt into a remote provider (OpenAI-compatible, Anthropic). Data leaves your server only when you configure and trigger it.</li><li><strong>Behaviour over charts.</strong> The Copilot applies proven principles — Pay Yourself First, Conscious Spending, Emergency Fund, Debt Snowball, Compound Growth — to your actual numbers and turns them into next steps.</li><li><strong>Self-hosting without ceremony.</strong> <code>docker compose up -d</code> is the whole install. Tailscale is the recommended path to HTTPS and PWA.</li></ul><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What lives there</th></tr></thead><tbody><tr><td><code>finsight-server</code></td><td>Serves UI, authenticated RPC API, CSV uploads, SSE events, <code>GET /api/openapi.json</code></td></tr><tr><td>Browser / PWA</td><td>Same-origin HTTP/SSE client; seven-day, read-only IndexedDB cache for offline viewing (purged on logout)</td></tr><tr><td><code>/data</code> on your server</td><td><code>users.db</code>, <code>session.key</code>, <code>users/&lt;uuid&gt;/data.sqlcipher</code> per user</td></tr></tbody></table><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li>Track net worth, income, and expenses from daily transactions</li><li>Plan with envelope budgets, goals, and cash-flow forecasting</li><li>Run what-if scenarios in natural language</li><li>Let rules and recipes handle repetition — pattern rules you can read</li><li>Ask the Copilot “what should I fix this month?” and get grounded answers with tool-cited figures</li></ul><p>Next: <a href="/FinSight/getting-started/what-is-finsight">What is FinSight?</a> — the product in one page.</p>',11)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
